#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Define the Record structure
struct Record {
    int id;
    char name[15];
    char surname[25];
    char address[50];
};

// Define the CHUNK structure
struct CHUNK {
    int file_desc;
    int from_BlockId;
    int to_BlockId;
    int recordsInChunk;
    int blocksInChunk;
    struct Record records[100]; // Specify the maximum number of records in a chunk
};

// Function to compare two records lexicographically
bool shouldSwap(struct Record* rec1, struct Record* rec2) {
    int nameComparison = strcmp(rec1->name, rec2->name);

    if (nameComparison < 0) {
        // rec1's name comes before rec2's name
        return true;
    } else if (nameComparison == 0) {
        // Names are equal, compare surnames
        int surnameComparison = strcmp(rec1->surname, rec2->surname);

        if (surnameComparison < 0) {
            // rec1's surname comes before rec2's surname
            return true;
        }
    }

    // No need to swap
    return false;
}

// Function to perform bubble sort on records within a chunk
void sort_Chunk(struct CHUNK* chunk) {
    int i, j;
    for (i = 0; i < chunk->recordsInChunk - 1; i++) {
        for (j = 0; j < chunk->recordsInChunk - i - 1; j++) {
            // Compare adjacent records and swap if needed
            if (shouldSwap(&chunk->records[j], &chunk->records[j + 1])) {
                // Swap records
                struct Record temp = chunk->records[j];
                chunk->records[j] = chunk->records[j + 1];
                chunk->records[j + 1] = temp;
            }
        }
    }
}

int main() {
    // Example usage
    struct CHUNK chunk = {0}; // Initialize the chunk with zero values

    // Initialize the chunk with some records
    // Note: You should populate the records array with actual data
    // before calling the sort_Chunk function.
    chunk.recordsInChunk = 5; // Example number of records
    for (int i = 0; i < chunk.recordsInChunk; i++) {
        chunk.records[i].id = i + 1;
        strncpy(chunk.records[i].name, "John", sizeof(chunk.records[i].name) - 1);
        chunk.records[i].name[sizeof(chunk.records[i].name) - 1] = '\0'; // Ensure null-termination
        strncpy(chunk.records[i].surname, "Doe", sizeof(chunk.records[i].surname) - 1);
        chunk.records[i].surname[sizeof(chunk.records[i].surname) - 1] = '\0'; // Ensure null-termination
        strncpy(chunk.records[i].address, "123 Main St", sizeof(chunk.records[i].address) - 1);
        chunk.records[i].address[sizeof(chunk.records[i].address) - 1] = '\0'; // Ensure null-termination
    }

    // Validate recordsInChunk
    if (chunk.recordsInChunk > sizeof(chunk.records) / sizeof(chunk.records[0])) {
        fprintf(stderr, "Error: recordsInChunk exceeds the maximum number of records.\n");
        return 1;
    }

    // Call the sort_Chunk function to sort the records in the chunk
    sort_Chunk(&chunk);

    // Display the sorted records (for demonstration purposes)
    for (int i = 0; i < chunk.recordsInChunk; i++) {
        printf("Record %d: %s %s\n", i + 1, chunk.records[i].name, chunk.records[i].surname);
    }

    return 0;
}
